.cu-upload {
  display: grid;
  gap: var(--cu-space-2);
  color: var(--cu-color-fg-default);
}

.cu-upload__dropzone {
  display: grid;
  justify-items: center;
  gap: var(--cu-space-2);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  border: 2px dashed var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  cursor: pointer;
  text-align: center;
}

.cu-upload--dragover .cu-upload__dropzone {
  border-color: var(--cu-color-palette-brand);
  background: color-mix(in srgb, var(--cu-color-palette-brand) 8%, var(--cu-color-background-default));
}

.cu-upload__dropzone:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 2px;
}

.cu-upload__browse {
  color: var(--cu-color-palette-brand);
  font-weight: 700;
}

.cu-upload__input {
  display: none;
}

.cu-upload__list {
  display: grid;
  gap: var(--cu-space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}

.cu-upload__file {
  display: flex;
  justify-content: space-between;
  gap: var(--cu-space-2);
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
}

.cu-upload__size {
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}

import { useRef, useState } from 'react'
import type { ClipboardEvent, DragEvent, KeyboardEvent } from 'react'
import './styles.css'

export interface UploadProps {
  label: string
  dropzoneLabel?: string
  browseLabel?: string
  multiple?: boolean
  onFiles?: (files: File[]) => void
  className?: string
}

export function Upload({
  label,
  dropzoneLabel = 'Drag files here',
  browseLabel = 'Browse files',
  multiple = true,
  onFiles,
  className,
}: UploadProps) {
  const [files, setFiles] = useState<File[]>([])
  const [dragover, setDragover] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)
  const classes = ['cu-upload', dragover ? 'cu-upload--dragover' : '', className].filter(Boolean).join(' ')
  const sizeFormat = new Intl.NumberFormat(undefined, {
    style: 'unit',
    unit: 'kilobyte',
    maximumFractionDigits: 0,
  })

  const accept = (incoming: Iterable<File>) => {
    const next = multiple ? [...files, ...incoming] : Array.from(incoming).slice(0, 1)
    setFiles(next)
    if (next.length > 0) onFiles?.(next)
  }

  const onDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setDragover(false)
    accept(event.dataTransfer.files)
  }

  const onPaste = (event: ClipboardEvent<HTMLDivElement>) => {
    if (event.clipboardData.files.length > 0) {
      event.preventDefault()
      accept(event.clipboardData.files)
    }
  }

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      inputRef.current?.click()
    }
  }

  return (
    <div
      className={classes}
      data-ai-role="upload" data-ai-intent="upload-file"
      data-ai-state={dragover ? 'dragover' : files.length > 0 ? 'uploading' : 'default'}
    >
      <div
        className="cu-upload__dropzone"
        role="button"
        tabIndex={0}
        aria-label={label}
        onDragOver={(event) => {
          event.preventDefault()
          setDragover(true)
        }}
        onDragLeave={() => setDragover(false)}
        onDrop={onDrop}
        onPaste={onPaste}
        onKeyDown={onKeyDown}
        onClick={() => inputRef.current?.click()}
      >
        <span className="cu-upload__hint">{dropzoneLabel}</span>
        <span className="cu-upload__browse">{browseLabel}</span>
      </div>
      <input
        ref={inputRef}
        className="cu-upload__input"
        type="file"
        multiple={multiple}
        tabIndex={-1}
        aria-hidden="true"
        onChange={(event) => accept(event.currentTarget.files ?? [])}
      />
      {files.length > 0 ? (
        <ul className="cu-upload__list">
          {files.map((file, index) => (
            <li key={`${file.name}-${index}`} className="cu-upload__file">
              <span className="cu-upload__name">{file.name}</span>
              <span className="cu-upload__size">{sizeFormat.format(Math.ceil(file.size / 1024))}</span>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  )
}
